import { world, system } from "@minecraft/server";
import { getSettings } from "../data/settings.js";

const KEEP_TAG = "keep";

system.runInterval(() => {
  for (const player of world.getPlayers()) {
    const settings = getSettings(player);
    const feature = settings.itemMagnet;
    if (!feature.enabled) continue;

    const inventory = player.getComponent("minecraft:inventory")?.container;
    if (!inventory) continue;

    const nearbyItems = player.dimension.getEntities({
      location: player.location,
      maxDistance: feature.radius,
      type: "minecraft:item"
    });

    for (const itemEntity of nearbyItems) {
      if (!itemEntity.isValid || itemEntity.hasTag(KEEP_TAG)) continue;

      const itemComp = itemEntity.getComponent("minecraft:item");
      if (!itemComp || !itemComp.itemStack) continue;

      const leftover = inventory.addItem(itemComp.itemStack);
      if (!leftover) {
        // fully picked up
        itemEntity.remove();
      }
      // if inventory is full (leftover exists), just leave the item on the ground
    }
  }
}, 10); // checked every 0.5 seconds (10 ticks)

