import { system, BlockPermutation, ItemStack } from "@minecraft/server";
import { getSettings } from "../data/settings.js";
import { getDropFor } from "../data/drops.js";
import { damageHeldTool } from "../data/durability.js";

system.beforeEvents.startup.subscribe((startupEvent) => {
  startupEvent.itemComponentRegistry.registerCustomComponent("__NS__:mining_3x3", {
    onMineBlock(event) {
      const { block, source, minedBlockPermutation } = event;
      if (!source) return;

      const settings = getSettings(source);
      const feature = settings.mining3x3;
      if (!feature.enabled) return;

      const typeId = minedBlockPermutation.type.id;
      if (!feature.blocks.includes(typeId)) return;

      breakSurrounding3x3(block, source, feature.blocks);
    }
  });
});

function breakSurrounding3x3(centerBlock, player, allowedBlocks) {
  const dimension = centerBlock.dimension;
  const view = player.getViewDirection();
  const axis = Math.abs(view.x) >= Math.abs(view.z) ? "x" : "z";

  const offsets = [];
  for (let a = -1; a <= 1; a++) {
    for (let b = -1; b <= 1; b++) {
      if (a === 0 && b === 0) continue;
      offsets.push(axis === "x" ? { x: 0, y: a, z: b } : { x: a, y: b, z: 0 });
    }
  }

  for (const off of offsets) {
    const pos = {
      x: centerBlock.location.x + off.x,
      y: centerBlock.location.y + off.y,
      z: centerBlock.location.z + off.z
    };

    const targetBlock = dimension.getBlock(pos);
    if (!targetBlock || !allowedBlocks.includes(targetBlock.typeId)) continue;

    const drop = getDropFor(targetBlock.typeId);
    try {
      dimension.spawnItem(
        new ItemStack(drop.item, drop.count),
        { x: pos.x + 0.5, y: pos.y + 0.5, z: pos.z + 0.5 }
      );
    } catch {
      // block has no direct item form - skip drop, still break it
    }

    targetBlock.setPermutation(BlockPermutation.resolve("minecraft:air"));
    damageHeldTool(player, 1);
  }
}

