import { world, BlockPermutation } from "@minecraft/server";
import { getSettings } from "../data/settings.js";
import { CROPS } from "../data/farming.js";

world.afterEvents.playerBreakBlock.subscribe((event) => {
  const { block, brokenBlockPermutation, player } = event;
  if (!player) return;

  const settings = getSettings(player);
  if (!settings.autoReplant?.enabled) return;

  const typeId = brokenBlockPermutation.type.id;
  const crop = CROPS[typeId];
  if (!crop) return;

  let stateValue;
  try {
    stateValue = brokenBlockPermutation.getState(crop.state);
  } catch {
    return; // block didn't have that state for some reason
  }
  if (stateValue !== crop.max) return; // only auto-replant when it was fully grown

  try {
    const newPermutation = BlockPermutation.resolve(typeId, { [crop.state]: 0 });
    block.setPermutation(newPermutation);
  } catch {
    // e.g. farmland below no longer valid - just skip replanting
  }
});

