import { world, system } from "@minecraft/server";
import { getSettings } from "../data/settings.js";

const KEEP_TAG = "keep"; // tag entities with "keep" to exclude them from clearing

// Per-player timers are kept in memory (no need to persist - just resets
// the countdown whenever the world reloads).
const elapsedByPlayer = new Map();

system.runInterval(() => {
  for (const player of world.getPlayers()) {
    const settings = getSettings(player);
    const feature = settings.clearLag;

    if (!feature.enabled) {
      elapsedByPlayer.delete(player.id);
      continue;
    }

    const elapsed = (elapsedByPlayer.get(player.id) ?? 0) + 1;
    const remaining = feature.intervalSeconds - elapsed;

    if (feature.warnSeconds > 0 && remaining === feature.warnSeconds) {
      player.sendMessage(`§e[ClearLag] Items & mobs around you (radius ${feature.radius}) will be cleared in ${feature.warnSeconds}s...`);
    }

    if (elapsed >= feature.intervalSeconds) {
      elapsedByPlayer.set(player.id, 0);
      runClearLagAround(player, feature.radius);
    } else {
      elapsedByPlayer.set(player.id, elapsed);
    }
  }
}, 20); // checked every 1 second (20 ticks)

function runClearLagAround(player, radius) {
  const dimension = player.dimension;
  let itemsRemoved = 0;
  let mobsRemoved = 0;

  const droppedItems = dimension.getEntities({
    location: player.location,
    maxDistance: radius,
    type: "minecraft:item"
  });
  for (const entity of droppedItems) {
    if (!entity.isValid || entity.hasTag(KEEP_TAG)) continue;
    entity.remove();
    itemsRemoved++;
  }

  const monsters = dimension.getEntities({
    location: player.location,
    maxDistance: radius,
    families: ["monster"]
  });
  for (const entity of monsters) {
    if (!entity.isValid || entity.hasTag(KEEP_TAG)) continue;
    entity.remove();
    mobsRemoved++;
  }

  player.sendMessage(`§a[ClearLag] Done around you: ${itemsRemoved} items, ${mobsRemoved} mobs cleared.`);
}

