import { system } from "@minecraft/server";
import { ActionFormData, ModalFormData } from "@minecraft/server-ui";
import {
  getSettings,
  saveSettings,
  CANDIDATE_MINING_BLOCKS,
  CANDIDATE_LOG_BLOCKS,
  CANDIDATE_ORE_BLOCKS,
  MAX_CLEARLAG_RADIUS
} from "../data/settings.js";

system.beforeEvents.startup.subscribe((startupEvent) => {
  startupEvent.itemComponentRegistry.registerCustomComponent("__NS__:open_menu", {
    onUse(event) {
      const player = event.source;
      if (!player) return;
      openMainMenu(player);
    }
  });
});

function openMainMenu(player) {
  const s = getSettings(player);

  const form = new ActionFormData()
    .title("§l§6Really Tools §7(your settings)")
    .body("Choose a feature to configure:")
    .button(`Mining 3x3 [${s.mining3x3.enabled ? "§aON" : "§cOFF"}§r]`)
    .button(`Axe Capitator [${s.capitator.enabled ? "§aON" : "§cOFF"}§r]`)
    .button(`Ore Vein [${s.oreVein.enabled ? "§aON" : "§cOFF"}§r]`)
    .button(`Clear Lag [${s.clearLag.enabled ? "§aON" : "§cOFF"}§r]`)
    .button(`Item Magnet [${s.itemMagnet.enabled ? "§aON" : "§cOFF"}§r]`)
    .button(`Farming (Sapling/Replant/Hoe)`);

  form.show(player).then((res) => {
    if (res.canceled) return;
    if (res.selection === 0) openBlockMenu(player, "mining3x3", "Mining 3x3", CANDIDATE_MINING_BLOCKS);
    if (res.selection === 1) openBlockMenu(player, "capitator", "Axe Capitator", CANDIDATE_LOG_BLOCKS);
    if (res.selection === 2) openBlockMenu(player, "oreVein", "Ore Vein", CANDIDATE_ORE_BLOCKS);
    if (res.selection === 3) openClearLagMenu(player);
    if (res.selection === 4) openMagnetMenu(player);
    if (res.selection === 5) openFarmingMenu(player);
  });
}

function openBlockMenu(player, key, label, candidateBlocks) {
  const settings = getSettings(player);
  const feature = settings[key];

  const form = new ModalFormData()
    .title(`§6${label}`)
    .toggle("§lEnable this feature", { defaultValue: feature.enabled });

  for (const blockId of candidateBlocks) {
    form.toggle(blockId.replace("minecraft:", ""), { defaultValue: feature.blocks.includes(blockId) });
  }

  form.show(player).then((res) => {
    if (res.canceled) {
      openMainMenu(player);
      return;
    }
    const values = res.formValues;
    feature.enabled = values[0];
    feature.blocks = candidateBlocks.filter((_, i) => values[i + 1]);

    settings[key] = feature;
    saveSettings(player, settings);
    player.sendMessage(`§a${label} saved (${feature.blocks.length} block types selected).`);
    openMainMenu(player);
  });
}

function openClearLagMenu(player) {
  const settings = getSettings(player);
  const feature = settings.clearLag;

  const form = new ModalFormData()
    .title("§6Clear Lag (around you)")
    .toggle("§lEnable automatic clear lag", { defaultValue: feature.enabled })
    .slider("Clear radius (blocks)", 1, MAX_CLEARLAG_RADIUS, { valueStep: 1, defaultValue: feature.radius })
    .slider("Clear interval (seconds)", 30, 1200, { valueStep: 30, defaultValue: feature.intervalSeconds })
    .slider("Warning before clearing (seconds)", 0, 60, { valueStep: 5, defaultValue: feature.warnSeconds });

  form.show(player).then((res) => {
    if (res.canceled) {
      openMainMenu(player);
      return;
    }
    const [enabled, radius, interval, warn] = res.formValues;
    feature.enabled = enabled;
    feature.radius = radius;
    feature.intervalSeconds = interval;
    feature.warnSeconds = warn;

    settings.clearLag = feature;
    saveSettings(player, settings);
    player.sendMessage(`§aClear Lag settings saved (radius ${radius} blocks, around you only).`);
    openMainMenu(player);
  });
}

function openMagnetMenu(player) {
  const settings = getSettings(player);
  const feature = settings.itemMagnet;

  const form = new ModalFormData()
    .title("§6Item Magnet")
    .toggle("§lEnable automatic item magnet", { defaultValue: feature.enabled })
    .slider("Radius (blocks)", 1, 16, { valueStep: 1, defaultValue: feature.radius });

  form.show(player).then((res) => {
    if (res.canceled) {
      openMainMenu(player);
      return;
    }
    const [enabled, radius] = res.formValues;
    feature.enabled = enabled;
    feature.radius = radius;

    settings.itemMagnet = feature;
    saveSettings(player, settings);
    player.sendMessage("§aItem Magnet settings saved.");
    openMainMenu(player);
  });
}

function openFarmingMenu(player) {
  const settings = getSettings(player);

  const form = new ModalFormData()
    .title("§6Farming")
    .toggle("§lAuto Sapling (replant on tree fell)", { defaultValue: settings.autoSapling.enabled })
    .toggle("§lAuto Replant (regrow mature crops)", { defaultValue: settings.autoReplant.enabled })
    .toggle("§lFarming Hoe: till 3x3", { defaultValue: settings.farmingHoe.enabled })
    .toggle("§lFarming Hoe: auto seed 3x3", { defaultValue: settings.farmingHoe.autoSeed });

  form.show(player).then((res) => {
    if (res.canceled) {
      openMainMenu(player);
      return;
    }
    const [sapling, replant, hoeEnabled, hoeAutoSeed] = res.formValues;
    settings.autoSapling.enabled = sapling;
    settings.autoReplant.enabled = replant;
    settings.farmingHoe.enabled = hoeEnabled;
    settings.farmingHoe.autoSeed = hoeAutoSeed;

    saveSettings(player, settings);
    player.sendMessage("§aFarming settings saved.");
    openMainMenu(player);
  });
}

