import { system, BlockPermutation, ItemStack } from "@minecraft/server";
import { getSettings } from "../data/settings.js";
import { getDropFor } from "../data/drops.js";
import { damageHeldTool } from "../data/durability.js";
import { SAPLING_MAP, NORMAL_TREE_GROUND, NETHER_TREE_GROUND } from "../data/farming.js";

const MAX_LOGS_PER_TREE = 128;

system.beforeEvents.startup.subscribe((startupEvent) => {
  startupEvent.itemComponentRegistry.registerCustomComponent("__NS__:axe_capitator", {
    onMineBlock(event) {
      const { block, source, minedBlockPermutation } = event;
      if (!source) return;

      const settings = getSettings(source);
      const feature = settings.capitator;
      if (!feature.enabled) return;

      const typeId = minedBlockPermutation.type.id;
      if (!feature.blocks.includes(typeId)) return;

      const lowestPos = fellConnectedLogs(block, feature.blocks, source);

      if (settings.autoSapling?.enabled && lowestPos) {
        plantSaplingAtBase(block.dimension, lowestPos, typeId);
      }
    }
  });
});

function fellConnectedLogs(startBlock, allowedLogs, player) {
  const dimension = startBlock.dimension;
  const startPos = startBlock.location;
  const visited = new Set([`${startPos.x},${startPos.y},${startPos.z}`]);
  const queue = [];
  let processed = 0;

  // lowestPos tracks the bottom-most log found, regardless of where the
  // player actually chopped - so the sapling always ends up at the base.
  let lowestPos = { ...startPos };

  // startBlock itself is already air (vanilla just mined it) - seed the
  // search with its neighbors instead of the (now empty) start position.
  for (let dx = -1; dx <= 1; dx++) {
    for (let dy = -1; dy <= 2; dy++) {
      for (let dz = -1; dz <= 1; dz++) {
        if (dx === 0 && dy === 0 && dz === 0) continue;
        queue.push({ x: startPos.x + dx, y: startPos.y + dy, z: startPos.z + dz });
      }
    }
  }

  while (queue.length > 0 && processed < MAX_LOGS_PER_TREE) {
    const pos = queue.shift();
    const key = `${pos.x},${pos.y},${pos.z}`;
    if (visited.has(key)) continue;
    visited.add(key);

    const b = dimension.getBlock(pos);
    if (!b || !allowedLogs.includes(b.typeId)) continue;

    processed++;
    if (pos.y < lowestPos.y) lowestPos = { x: pos.x, y: pos.y, z: pos.z };

    const drop = getDropFor(b.typeId);
    try {
      dimension.spawnItem(
        new ItemStack(drop.item, drop.count),
        { x: pos.x + 0.5, y: pos.y + 0.5, z: pos.z + 0.5 }
      );
    } catch { /* ignore */ }
    b.setPermutation(BlockPermutation.resolve("minecraft:air"));
    if (player) damageHeldTool(player, 1);

    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 2; dy++) {
        for (let dz = -1; dz <= 1; dz++) {
          if (dx === 0 && dy === 0 && dz === 0) continue;
          queue.push({ x: pos.x + dx, y: pos.y + dy, z: pos.z + dz });
        }
      }
    }
  }

  return processed > 0 ? lowestPos : null;
}

function plantSaplingAtBase(dimension, lowestLogPos, logTypeId) {
  const saplingId = SAPLING_MAP[logTypeId];
  if (!saplingId) return;

  const groundPos = { x: lowestLogPos.x, y: lowestLogPos.y - 1, z: lowestLogPos.z };
  const ground = dimension.getBlock(groundPos);
  if (!ground) return;

  const isNetherStem = logTypeId === "minecraft:crimson_stem" || logTypeId === "minecraft:warped_stem";
  const validGround = isNetherStem ? NETHER_TREE_GROUND : NORMAL_TREE_GROUND;
  if (!validGround.includes(ground.typeId)) return;

  const plantSpot = dimension.getBlock(lowestLogPos);
  if (!plantSpot || plantSpot.typeId !== "minecraft:air") return; // spot must be clear

  try {
    plantSpot.setPermutation(BlockPermutation.resolve(saplingId));
  } catch { /* some saplings (e.g. mangrove_propagule) may refuse odd placements - safe to ignore */ }
}

