import { system, BlockPermutation, EquipmentSlot } from "@minecraft/server";
import { getSettings } from "../data/settings.js";
import { TILLABLE_BLOCKS, SEED_TO_CROP } from "../data/farming.js";

system.beforeEvents.startup.subscribe((startupEvent) => {
  startupEvent.itemComponentRegistry.registerCustomComponent("__NS__:hoe_3x3", {
    onUseOn(event) {
      const { block, source } = event;
      if (!source) return;

      const settings = getSettings(source);
      const feature = settings.farmingHoe;
      if (!feature.enabled) return;

      const tilledSpots = tillSurrounding3x3(block);

      if (feature.autoSeed && tilledSpots.length > 0) {
        autoPlantSeeds3x3(source, tilledSpots);
      }
    }
  });
});

function tillSurrounding3x3(centerBlock) {
  const dimension = centerBlock.dimension;
  const center = centerBlock.location;
  const tilled = [];

  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      const pos = { x: center.x + dx, y: center.y, z: center.z + dz };
      const target = dimension.getBlock(pos);
      if (!target || !TILLABLE_BLOCKS.includes(target.typeId)) continue;

      const above = dimension.getBlock({ x: pos.x, y: pos.y + 1, z: pos.z });
      if (!above || above.typeId !== "minecraft:air") continue; // needs clear space to be farmland

      try {
        target.setPermutation(BlockPermutation.resolve("minecraft:farmland"));
        tilled.push(pos);
      } catch { /* skip this tile */ }
    }
  }

  return tilled;
}

function autoPlantSeeds3x3(player, tilledSpots) {
  const equippable = player.getComponent("minecraft:equippable");
  if (!equippable) return;

  const offhandStack = equippable.getEquipment(EquipmentSlot.Offhand);
  if (!offhandStack) return;

  const cropId = SEED_TO_CROP[offhandStack.typeId];
  if (!cropId) return;

  const dimension = player.dimension;
  let remainingSeeds = offhandStack.amount;

  for (const pos of tilledSpots) {
    if (remainingSeeds <= 0) break;

    const abovePos = { x: pos.x, y: pos.y + 1, z: pos.z };
    const above = dimension.getBlock(abovePos);
    if (!above || above.typeId !== "minecraft:air") continue;

    try {
      above.setPermutation(BlockPermutation.resolve(cropId));
      remainingSeeds--;
    } catch { /* skip this tile */ }
  }

  const usedSeeds = offhandStack.amount - remainingSeeds;
  if (usedSeeds <= 0) return;

  if (remainingSeeds <= 0) {
    equippable.setEquipment(EquipmentSlot.Offhand, undefined);
  } else {
    offhandStack.amount = remainingSeeds;
    equippable.setEquipment(EquipmentSlot.Offhand, offhandStack);
  }
}

