// so everyone can configure their own tools independently.

const KEY = "__NS__:tool_settings";

export const CANDIDATE_MINING_BLOCKS = [
  "minecraft:stone",
  "minecraft:deepslate",
  "minecraft:cobblestone",
  "minecraft:cobbled_deepslate",
  "minecraft:netherrack",
  "minecraft:end_stone",
  "minecraft:blackstone",
  "minecraft:granite",
  "minecraft:diorite",
  "minecraft:andesite"
];

export const CANDIDATE_LOG_BLOCKS = [
  "minecraft:oak_log",
  "minecraft:birch_log",
  "minecraft:spruce_log",
  "minecraft:jungle_log",
  "minecraft:acacia_log",
  "minecraft:dark_oak_log",
  "minecraft:mangrove_log",
  "minecraft:cherry_log",
  "minecraft:crimson_stem",
  "minecraft:warped_stem"
];

export const CANDIDATE_ORE_BLOCKS = [
  "minecraft:coal_ore",
  "minecraft:iron_ore",
  "minecraft:gold_ore",
  "minecraft:diamond_ore",
  "minecraft:emerald_ore",
  "minecraft:lapis_ore",
  "minecraft:redstone_ore",
  "minecraft:copper_ore",
  "minecraft:deepslate_coal_ore",
  "minecraft:deepslate_iron_ore",
  "minecraft:deepslate_gold_ore",
  "minecraft:deepslate_diamond_ore",
  "minecraft:deepslate_emerald_ore",
  "minecraft:deepslate_lapis_ore",
  "minecraft:deepslate_redstone_ore",
  "minecraft:deepslate_copper_ore",
  "minecraft:nether_gold_ore",
  "minecraft:nether_quartz_ore",
  "minecraft:ancient_debris"
];

export const MAX_CLEARLAG_RADIUS = 20;

function defaultSettings() {
  return {
    mining3x3: { enabled: true, blocks: [...CANDIDATE_MINING_BLOCKS] },
    capitator: { enabled: true, blocks: [...CANDIDATE_LOG_BLOCKS] },
    oreVein: { enabled: true, blocks: [...CANDIDATE_ORE_BLOCKS] },
    clearLag: { enabled: true, intervalSeconds: 300, warnSeconds: 10, radius: MAX_CLEARLAG_RADIUS },
    itemMagnet: { enabled: true, radius: 6 },
    autoSapling: { enabled: true },
    autoReplant: { enabled: true },
    farmingHoe: { enabled: true, autoSeed: true }
  };
}

/**
 * @param {import("@minecraft/server").Player} player
 */
export function getSettings(player) {
  const defaults = defaultSettings();
  if (!player || typeof player.getDynamicProperty !== "function") return defaults;

  const raw = player.getDynamicProperty(KEY);
  if (typeof raw !== "string") return defaults;

  try {
    const parsed = JSON.parse(raw);
    return {
      mining3x3: { ...defaults.mining3x3, ...parsed.mining3x3 },
      capitator: { ...defaults.capitator, ...parsed.capitator },
      oreVein: { ...defaults.oreVein, ...parsed.oreVein },
      clearLag: { ...defaults.clearLag, ...parsed.clearLag },
      itemMagnet: { ...defaults.itemMagnet, ...parsed.itemMagnet },
      autoSapling: { ...defaults.autoSapling, ...parsed.autoSapling },
      autoReplant: { ...defaults.autoReplant, ...parsed.autoReplant },
      farmingHoe: { ...defaults.farmingHoe, ...parsed.farmingHoe }
    };
  } catch {
    return defaults;
  }
}

/**
 * @param {import("@minecraft/server").Player} player
 */
export function saveSettings(player, settings) {
  if (!player || typeof player.setDynamicProperty !== "function") return;
  player.setDynamicProperty(KEY, JSON.stringify(settings));
}

