import { EquipmentSlot } from "@minecraft/server";

/**
 * Manually damages the tool currently held by `player` by `amount` points.
 * Works alongside Mending naturally: Mending repairs durability whenever the
 * player picks up XP orbs, regardless of how the durability damage was applied,
 * so no extra code is needed to "support" Mending - it just works.
 */
export function damageHeldTool(player, amount = 1) {
  if (!player || typeof player.getComponent !== "function") return;

  const equippable = player.getComponent("minecraft:equippable");
  if (!equippable) return;

  const itemStack = equippable.getEquipment(EquipmentSlot.Mainhand);
  if (!itemStack) return;

  const durability = itemStack.getComponent("minecraft:durability");
  if (!durability) return; // item has no durability component, nothing to damage

  const newDamage = durability.damage + amount;

  if (newDamage >= durability.maxDurability) {
    // tool breaks
    equippable.setEquipment(EquipmentSlot.Mainhand, undefined);
    player.dimension.playSound("random.break", player.location);
  } else {
    durability.damage = newDamage;
    equippable.setEquipment(EquipmentSlot.Mainhand, itemStack);
  }
}

