import { system, world } from "@minecraft/server";
import { FOOD_SATURATION } from "./food_saturation.js";

const MAX_SATURATION = 20;

system.runInterval(() => {
    for (const player of world.getAllPlayers()) {
        const health = player.getComponent("health");
        if (!health || health.currentValue <= 0) continue;

        let saturation = player.getDynamicProperty("saturation") || 0;

        if (saturation >= 1 && health.currentValue < health.effectiveMax) {
            health.setCurrentValue(health.currentValue + 1);
            player.setDynamicProperty("saturation", saturation - 1);

            player.addEffect("hunger", 3, { amplifier: 254, showParticles: false });
        }
    }
}, 10);

world.afterEvents.itemCompleteUse.subscribe(({ itemStack, source }) => {
    const satValue = FOOD_SATURATION[itemStack.typeId];
    if (!satValue) return;

    const current = source.getDynamicProperty("saturation") || 0;
    const total = Math.min(current + satValue, MAX_SATURATION);
    source.setDynamicProperty("saturation", total);
});

world.afterEvents.entityDie.subscribe(({ deadEntity }) => {
    if (deadEntity?.typeId === "minecraft:player") {
        deadEntity.setDynamicProperty("saturation", 6);
    }
});

world.afterEvents.playerSpawn.subscribe(({ player }) => {
    if (!player.hasTag("saturation_initialized")) {
        player.setDynamicProperty("saturation", 6);
        player.addTag("saturation_initialized");
    }
});

world.beforeEvents.effectAdd.subscribe((e) => {
    if (e.effectType === "Hunger" && e.duration > 5) e.cancel = true;
});

